        children: "public final class PersistenceExceptionTranslator {\n\n    public RuntimeException translate(RuntimeException exception) {\n        Throwable root = rootCause(exception);\n\n        if (root instanceof SQLException sqlException) {\n            return translateSqlException(sqlException, exception);\n        }\n\n        return new PersistenceException(\n                \"PERSISTENCE_ERROR\",\n                \"Persistence operation failed\",\n                PersistenceErrorCategory.UNKNOWN,\n                exception\n        );\n    }\n\n    private RuntimeException translateSqlException(\n            SQLException sqlException,\n            RuntimeException original\n    ) {\n        return switch (sqlException.getSQLState()) {\n            case \"23505\" -> new PersistenceException(\n                    \"DUPLICATE_RESOURCE\",\n                    \"Resource already exists\",\n                    PersistenceErrorCategory.CONFLICT,\n                    original\n            );\n\n            case \"23503\" -> new PersistenceException(\n                    \"REFERENCE_NOT_FOUND\",\n                    \"Referenced resource was not found\",\n                    PersistenceErrorCategory.CONFLICT,\n                    original\n            );\n\n            case \"23514\" -> new PersistenceException(\n                    \"CONSTRAINT_VIOLATION\",\n                    \"Persistence constraint was violated\",\n                    PersistenceErrorCategory.CONFLICT,\n                    original\n            );\n\n            case \"40001\", \"40P01\" -> new PersistenceException(\n                    \"CONCURRENT_MODIFICATION\",\n                    \"Resource was modified concurrently\",\n                    PersistenceErrorCategory.CONFLICT,\n                    original\n            );\n\n            case \"57014\" -> new PersistenceException(\n                    \"QUERY_TIMEOUT\",\n                    \"Database query timed out\",\n                    PersistenceErrorCategory.TIMEOUT,\n                    original\n            );\n\n            default -> new PersistenceException(\n                    \"PERSISTENCE_ERROR\",\n                    \"Persistence operation failed\",\n                    PersistenceErrorCategory.UNKNOWN,\n                    original\n            );\n        };\n    }\n\n    private Throwable rootCause(Throwable throwable) {\n        Throwable current = throwable;\n\n        while (current.getCause() != null) {\n            current = current.getCause();\n        }\n\n        return current;\n    }\n}\n"
