        children: "public final class MyBatisOrderRepository implements OrderRepository {\n\n    private final OrderSqlMapper sqlMapper;\n    private final OrderPersistenceMapper persistenceMapper;\n\n    public MyBatisOrderRepository(\n            SqlSession session,\n            OrderPersistenceMapper persistenceMapper\n    ) {\n        this.sqlMapper = session.getMapper(OrderSqlMapper.class);\n        this.persistenceMapper = persistenceMapper;\n    }\n\n    @Override\n    public void save(Order order) {\n        OrderRecord existing = sqlMapper.findByIdForTenant(\n                order.tenantId().value(),\n                order.id()\n        );\n\n        if (existing == null) {\n            insert(order);\n        } else {\n            update(order);\n        }\n    }\n\n    @Override\n    public Optional<Order> findById(TenantId tenantId, UUID orderId) {\n        OrderRecord record = sqlMapper.findByIdForTenant(\n                tenantId.value(),\n                orderId\n        );\n\n        if (record == null) {\n            return Optional.empty();\n        }\n\n        List<OrderItemRecord> items =\n                sqlMapper.findItemsByOrderIdForTenant(\n                        tenantId.value(),\n                        orderId\n                );\n\n        return Optional.of(persistenceMapper.toDomain(record, items));\n    }\n\n    @Override\n    public Optional<Order> findByIdForUpdate(\n            TenantId tenantId,\n            UUID orderId\n    ) {\n        OrderRecord record = sqlMapper.findByIdForTenantForUpdate(\n                tenantId.value(),\n                orderId\n        );\n\n        if (record == null) {\n            return Optional.empty();\n        }\n\n        List<OrderItemRecord> items =\n                sqlMapper.findItemsByOrderIdForTenant(\n                        tenantId.value(),\n                        orderId\n                );\n\n        return Optional.of(persistenceMapper.toDomain(record, items));\n    }\n\n    private void insert(Order order) {\n        OrderRecord orderRecord = persistenceMapper.toRecord(order);\n        sqlMapper.insertOrder(orderRecord);\n\n        List<OrderItemRecord> itemRecords =\n                persistenceMapper.toItemRecords(order);\n\n        for (OrderItemRecord item : itemRecords) {\n            sqlMapper.insertOrderItem(item);\n        }\n    }\n\n    private void update(Order order) {\n        OrderRecord orderRecord = persistenceMapper.toRecord(order);\n\n        int rows = sqlMapper.updateOrder(orderRecord);\n\n        if (rows == 0) {\n            throw new PersistenceException(\n                    \"VERSION_CONFLICT\",\n                    \"Resource version conflict\",\n                    PersistenceErrorCategory.CONFLICT\n            );\n        }\n    }\n\n    @Override\n    public List<Order> findSubmittedOrdersForCustomer(\n            TenantId tenantId,\n            UUID customerId,\n            int limit\n    ) {\n        List<OrderRecord> records =\n                sqlMapper.findSubmittedOrdersForCustomer(\n                        tenantId.value(),\n                        customerId,\n                        limit\n                );\n\n        if (records.isEmpty()) {\n            return List.of();\n        }\n\n        List<UUID> orderIds = records.stream()\n                .map(OrderRecord::id)\n                .toList();\n\n        List<OrderItemRecord> items =\n                sqlMapper.findItemsByOrderIdsForTenant(\n                        tenantId.value(),\n                        orderIds\n                );\n\n        Map<UUID, List<OrderItemRecord>> itemsByOrderId =\n                items.stream()\n                        .collect(Collectors.groupingBy(\n                                OrderItemRecord::orderId\n                        ));\n\n        return records.stream()\n                .map(record -> persistenceMapper.toDomain(\n                        record,\n                        itemsByOrderId.getOrDefault(\n   